-- qnViewPort: englische Texte (alle Clients außer deDE). Schlüssel = deutscher Text im Code.
-- Apply/Reset kommen als APPLY/RESET von Blizzard.

local ADDON, ns = ...
local L = qnCore.NewLocale(ns, ADDON)
if qnCore.GERMAN then return end

